import { Chart, registerables } from "chart.js";
import { db } from "../../firebase"; // Ensure you have Firebase initialized
import { collection, getDocs } from "firebase/firestore";

Chart.register(...registerables);

// Custom Rounded Bar Functionality
Chart.elements.Rectangle.prototype.draw = function () {
  var ctx = this._chart.ctx;
  var vm = this._view;
  var left, right, top, bottom, signX, signY, borderSkipped;
  var borderWidth = vm.borderWidth;
  var cornerRadius = 6;

  if (!vm.horizontal) {
    left = vm.x - vm.width / 2;
    right = vm.x + vm.width / 2;
    top = vm.y;
    bottom = vm.base;
    signX = 1;
    signY = bottom > top ? 1 : -1;
    borderSkipped = vm.borderSkipped || "bottom";
  } else {
    left = vm.base;
    right = vm.x;
    top = vm.y - vm.height / 2;
    bottom = vm.y + vm.height / 2;
    signX = right > left ? 1 : -1;
    signY = 1;
    borderSkipped = vm.borderSkipped || "left";
  }

  if (borderWidth) {
    var barSize = Math.min(Math.abs(left - right), Math.abs(top - bottom));
    borderWidth = borderWidth > barSize ? barSize : borderWidth;
    var halfStroke = borderWidth / 2;
    var borderLeft = left + (borderSkipped !== "left" ? halfStroke * signX : 0);
    var borderRight = right + (borderSkipped !== "right" ? -halfStroke * signX : 0);
    var borderTop = top + (borderSkipped !== "top" ? halfStroke * signY : 0);
    var borderBottom = bottom + (borderSkipped !== "bottom" ? -halfStroke * signY : 0);

    if (borderLeft !== borderRight) {
      top = borderTop;
      bottom = borderBottom;
    }
    if (borderTop !== borderBottom) {
      left = borderLeft;
      right = borderRight;
    }
  }

  ctx.beginPath();
  ctx.fillStyle = vm.backgroundColor;
  ctx.strokeStyle = vm.borderColor;
  ctx.lineWidth = borderWidth;

  var corners = [
    [left, bottom],
    [left, top],
    [right, top],
    [right, bottom],
  ];

  var borders = ["bottom", "left", "top", "right"];
  var startCorner = borders.indexOf(borderSkipped, 0);
  if (startCorner === -1) {
    startCorner = 0;
  }

  function cornerAt(index) {
    return corners[(startCorner + index) % 4];
  }

  var corner = cornerAt(0);
  ctx.moveTo(corner[0], corner[1]);

  for (var i = 1; i < 4; i++) {
    corner = cornerAt(i);
    let width = corners[2][0] - corners[1][0];
    let height = corners[0][1] - corners[1][1];
    let x = corners[1][0];
    let y = corners[1][1];

    var radius = cornerRadius;
    if (radius > height / 2) {
      radius = height / 2;
    }
    if (radius > width / 2) {
      radius = width / 2;
    }

    ctx.moveTo(x + radius, y);
    ctx.lineTo(x + width - radius, y);
    ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
    ctx.lineTo(x + width, y + height - radius);
    ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
    ctx.lineTo(x + radius, y + height);
    ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
    ctx.lineTo(x, y + radius);
    ctx.quadraticCurveTo(x, y, x + radius, y);
  }

  ctx.fill();
  if (borderWidth) {
    ctx.stroke();
  }
};

// Fetch Data from Firebase
const fetchChartData = async (collectionName) => {
  try {
    const querySnapshot = await getDocs(collection(db, collectionName));
    const data = querySnapshot.docs.map((doc) => doc.data());

    if (!data.length) return { labels: [], values: [] };

    const monthOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const sortedData = data
      .filter((d) => d.month && d.value)
      .sort((a, b) => monthOrder.indexOf(a.month) - monthOrder.indexOf(b.month));

    return {
      labels: sortedData.map((d) => d.month),
      values: sortedData.map((d) => parseFloat(d.value) || 0),
    };
  } catch (error) {
    console.error(`Error fetching ${collectionName} data:`, error);
    return { labels: [], values: [] };
  }
};

// Chart Configurations
let chartExample1 = {
  options: {
    scales: {
      yAxes: [
        {
          gridLines: { color: "#e9ecef", zeroLineColor: "#e9ecef" },
          ticks: {
            callback: function (value) {
              if (!(value % 10)) {
                return value + " kg CO₂";
              }
            },
          },
        },
      ],
    },
    tooltips: {
      callbacks: {
        label: function (item, data) {
          var label = data.datasets[item.datasetIndex].label || "";
          return label + ": " + item.yLabel + " kg CO₂";
        },
      },
    },
  },

  data1: async () => {
    const { labels, values } = await fetchChartData("carbonFootprint");
    return {
      labels,
      datasets: [
        {
          label: "Carbon Emissions (kg CO₂)",
          data: values,
          backgroundColor: "#5e72e4",
          borderColor: "#172b4d",
          borderWidth: 2,
        },
      ],
    };
  },

  data2: async () => {
    const { labels, values } = await fetchChartData("performance");
    return {
      labels,
      datasets: [
        {
          label: "Performance",
          data: values,
          backgroundColor: "#2dce89",
          borderColor: "#1e7e34",
          borderWidth: 2,
        },
      ],
    };
  },
};

let chartExample2 = {
  options: {
    scales: {
      yAxes: [
        {
          ticks: {
            callback: function (value) {
              if (!(value % 10)) {
                return value;
              }
            },
          },
        },
      ],
    },
    tooltips: {
      callbacks: {
        label: function (item, data) {
          var label = data.datasets[item.datasetIndex].label || "";
          return label + ": " + item.yLabel;
        },
      },
    },
  },
  data: {
    labels: ["Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
    datasets: [
      {
        label: "Sales",
        data: [0, 0, 30, 22, 17, 29],
        maxBarThickness: 10,
      },
    ],
  },
};

export { chartExample1, chartExample2 };
